#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* sum 一定要初始化为 0。
       局部变量不初始化时里面是内存里的随机值，
       累加出来的结果会是一堆垃圾数据。 */
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i;
    }

    printf("%d\n", sum);
    return 0;
}

