#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* 累乘要从 1 开始！从 0 开始的话，乘什么都是 0。
       0! 按定义等于 1，这样写正好也对。 */
    long long fact = 1;

    int i = 1;
    while (i <= n) {
        fact *= i;
        i++;          /* 漏掉这一句就是死循环：i 永远是 1 */
    }

    /* 20! 远超过 int 的范围，所以用 long long，输出格式是 %lld */
    printf("%lld\n", fact);
    return 0;
}

