#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* do-while 先执行一次循环体，再判断条件。
       如果这里写成 while (n > 0)，n = 0 时一次都不执行，
       位数会是 0；而 0 本身是 1 位数。 */
    int count = 0;
    do {
        count++;
        n /= 10;      /* 整数除法：123 / 10 得到 12，正好去掉最后一位 */
    } while (n > 0);  /* 这一行末尾的分号不能少 */

    printf("%d\n", count);
    return 0;
}

