#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* 0 和 1 都不是素数，先单独处理掉，否则后面的循环会漏判 */
    int is_prime = 1;
    if (n < 2) {
        is_prime = 0;
    }

    /* 只需要试除到根号 n：如果 n 有一个大于根号 n 的因子，
       那必然有一个小于根号 n 的因子，早就被发现了。
       i * i <= n 比 sqrt() 更省事，也不用引入 math.h。 */
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            is_prime = 0;
            break;    /* 已经确定不是素数，再往下试没有意义 */
        }
    }

    if (is_prime) {
        printf("yes\n");
    } else {
        printf("no\n");
    }
    return 0;
}

