#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int count = 0;
    int sum = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        /* 非正数不参与统计：continue 直接跳到下一轮循环，
           省掉一层 if 嵌套。注意它是「跳过本次」，
           不是「结束整个循环」——那是 break。 */
        if (x <= 0) {
            continue;
        }

        count++;
        sum += x;
    }

    /* n = 0 时循环体一次都不执行，输出 0 0，这是对的 */
    printf("%d %d\n", count, sum);
    return 0;
}

