#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    /* 外层循环走一步（一行），内层循环就要走完一整圈（把这一行的星号印完） */
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            printf("*");
        }
        /* 换行必须写在内层循环结束之后、外层循环里面。
           写进内层循环就会变成每颗星单独占一行。 */
        printf("\n");
    }
    return 0;
}

